/**
 * Flag files that are not named after their country's code.
 *
 * Generated by `.tmp/ui-flags/build_flag_names.py` — do not edit by hand.
 * `code` is the ISO 3166-1 alpha-2 code the GeoIP dataset reports; the value is the
 * file's own name. Each entry is the result of comparing the file names in
 * `src/country-flags/` against the names of that country (common name, official
 * name, CIOC code and alt spellings) from
 * https://github.com/mledoze/countries — never of looking at the picture.
 */

/** Where a code's flag file is named after something else. (4 entries.) */
export const COUNTRY_FLAG_FILES: Record<string, string> = {
  /* CW: matched 'Curaçao' */
  CW: 'curacao',
  /* GB: matched 'UK' */
  GB: 'uk',
  /* SX: matched 'Sint Maarten' */
  SX: 'sint_maarten',
  /* XK: matched 'Kosovo' */
  XK: 'kosovo',
}
